import { useEffect, useState } from "react";
import MenuGrid from "./MenuGrid";
import Cart from "./Cart";
import UserOrders from "./UserOrders";
import { useAuth } from "../../context/AuthContext";
import Recommendations from "./Recommendations";
import PaymentModal from "./PaymentModal";
import "../../styles/canteen-ui.css";

export default function UserPanel() {
  const { user, logout } = useAuth();

  const [cart, setCart] = useState([]);
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);
  const [showPayment, setShowPayment] = useState(false);

  // 🆕 TAB STATE
  const [activeTab, setActiveTab] = useState("home"); // home | menu | cart | orders

  /* =========================
     CART LOGIC (UNCHANGED)
  ========================= */

  const addToCart = (item) => {
    setCart((prev) => {
      const existing = prev.find((i) => i.id === item.id);

      if (existing) {
        return prev.map((i) =>
          i.id === item.id
            ? { ...i, quantity: i.quantity + 1 }
            : i
        );
      }

      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const removeFromCart = (itemId) => {
    setCart((prev) =>
      prev
        .map((i) =>
          i.id === itemId
            ? { ...i, quantity: i.quantity - 1 }
            : i
        )
        .filter((i) => i.quantity > 0)
    );
  };

  /* =========================
     FINAL ORDER
  ========================= */

  const finalizeOrder = async () => {
    if (!user || cart.length === 0) return;

    const items = cart;
    const total = items.reduce(
      (sum, i) => sum + i.price * i.quantity,
      0
    );
    const order_id = Date.now();

    setOrders((prev) => [
      { order_id, items, total, status: "Pending" },
      ...prev,
    ]);

    try {
      await fetch("http://localhost:8000/api/orders/create/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          order_id,
          user: user.username,
          items,
          total,
        }),
      });

      setCart([]);
    } catch (err) {
      console.error("Order failed", err);
    }
  };

  /* =========================
     PAYMENT
  ========================= */

  const startPayment = () => {
    if (cart.length === 0) return;
    setShowPayment(true);
  };

  const handlePaymentSuccess = () => {
    setShowPayment(false);
    finalizeOrder();
    setActiveTab("orders");
  };

  const handlePaymentCancel = () => {
    setShowPayment(false);
  };

  /* =========================
     MENU AUTO LOAD
  ========================= */

  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:8000/api/menu/?college=${user.college}`)
      .then((res) => res.json())
      .then(setMenu)
      .catch(() => {});
  }, [user]);

  if (!user) return null;

  const totalAmount = cart.reduce(
    (s, i) => s + i.price * i.quantity,
    0
  );

  /* =========================
     UI
  ========================= */

  return (
    <div>
      <header>
        <h2>Welcome {user.username}</h2>
        <p style={{ fontSize: "14px", opacity: 0.8 }}>
          College: {user.college}
        </p>
        <button onClick={logout}>Logout</button>
      </header>

      {/* 🏠 HOME SCREEN */}
      {activeTab === "home" && (
        <div className="user-home">
          <div className="home-card" onClick={() => setActiveTab("menu")}>
            🍽
            <span>Menu</span>
          </div>
          <div className="home-card" onClick={() => setActiveTab("cart")}>
            🛒
            <span>Cart</span>
          </div>
          <div className="home-card" onClick={() => setActiveTab("orders")}>
            📦
            <span>Orders</span>
          </div>
        </div>
      )}

      {/* 🍽 MENU TAB */}
      {activeTab === "menu" && (
        <>
          <button onClick={() => setActiveTab("home")}>⬅ Back</button>
          <Recommendations addToCart={addToCart} />
          <MenuGrid
            menu={menu}
            cart={cart}
            addToCart={addToCart}
            removeFromCart={removeFromCart}
          />
        </>
      )}

      {/* 🛒 CART TAB */}
      {activeTab === "cart" && (
        <>
          <button onClick={() => setActiveTab("home")}>⬅ Back</button>
          <Cart
            cart={cart}
            removeFromCart={removeFromCart}
            placeOrder={startPayment}
          />
        </>
      )}

      {/* 📦 ORDERS TAB */}
      {activeTab === "orders" && (
        <>
          <button onClick={() => setActiveTab("home")}>⬅ Back</button>
          <UserOrders orders={orders} />
        </>
      )}

      {/* 💳 PAYMENT */}
      {showPayment && (
        <PaymentModal
          total={totalAmount}
          onCancel={handlePaymentCancel}
          onSuccess={handlePaymentSuccess}
        />
      )}
    </div>
  );
}
